
export default Vue.extend({
  name: 'ProgressBar',
  props: {
    progress: {
      type: Number,
      default: 50,
    },
    min: {
      type: Number,
      default: 0,
    },
    max: {
      type: Number,
      default: 100,
    },
    transition: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    width() {
      let progress = this.progress as number
      if (progress > this.max) {
        progress = this.max
      } else if (progress < this.min) {
        progress = this.min
      }
      const percent: number = (progress - this.min) / (this.max - this.min)
      return `${100 * percent}%`
    },
  },
})
